// Station lookup by the names a user types in Garmin Connect settings.
//
// stations.json is generated by scripts/build-stations.mjs from the Yandex
// `stations_list` method (~35 MB) and holds every Russian railway stop:
//   {"regions": [title, …],
//    "rows": [[yandexCode, title, direction, regionIndex, settlement, lat, lon], …]}
// sorted by title. It is Yandex data, so it is built at deploy time and not
// committed; without it only station codes resolve.
//
// Names repeat across Russia ("Заводская" in five regions, 140 Moscow names
// exist elsewhere too), so Home and Work are resolved as a pair: of all
// candidate pairs the closest one wins, since both ends of a suburban trip are
// near each other. "Name, city" (or region, or direction) narrows a name down.
// Unqualified names that the Moscow-only resolver understood keep its answer
// (see legacyPair), so existing settings behave as before. When a choice is
// left, the user gets a list of what to type.
const MOSCOW_REGION = "Москва и Московская область";

let DATA = { regions: [], rows: [] };
try {
  DATA = upgrade(require("./stations.json"));
} catch {
  // not built yet
}

// A stations.json built before all of Russia: Moscow rows [code, title, direction].
function upgrade(data) {
  if (!Array.isArray(data)) return data;
  return { regions: [MOSCOW_REGION], rows: data.map(([code, title, direction]) => [code, title, direction, 0, "", null, null]) };
}
// Pairs farther apart than this are not considered while closer ones exist.
const MAX_ROUTE_KM = 400;
// Candidates per name: enough for the worst homonym ("4 км" × 18) and keeps
// the pair search far below the Workers CPU limit.
const MAX_CANDIDATES = 60;
const UNKNOWN_KM = 150;
const MAX_OPTIONS = 6;
const NAME_CACHE_MAX = 2000;

const CODE_RE = /^s\d+$/;
const NOISE = new Set(["платформа", "пл", "станция", "ст", "оп", "о", "п"]);
const ALIASES = new Map([
  ["спб", "санкт петербург"],
  ["питер", "санкт петербург"],
  ["мск", "москва"],
  ["екб", "екатеринбург"],
  ["нск", "новосибирск"],
]);

// JS `\b` is ASCII-only, so words are split explicitly to drop "пл.", "ст." etc.
function normalize(name) {
  return String(name)
    .toLowerCase()
    .replace(/ё/g, "е")
    .split(/[^a-zа-я0-9]+/)
    .filter((w) => w && !NOISE.has(w))
    .join(" ");
}

// Turns stations.json into searchable station objects. Titles are normalized
// once per isolate, at startup, which has its own CPU budget on Workers.
function buildIndex(data) {
  const stations = data.rows.map(([code, title, direction, region, settlement, lat, lon], index) => {
    const norm = normalize(title);
    const regionTitle = data.regions[region] ?? "";
    return {
      index,
      code,
      title,
      direction: direction ?? "",
      region: regionTitle,
      settlement: settlement ?? "",
      lat: lat ?? null,
      lon: lon ?? null,
      norm,
      words: norm.split(" "),
      moscow: regionTitle === MOSCOW_REGION,
    };
  });
  return { stations, byCode: new Map(stations.map((s) => [s.code, s])), byName: new Map() };
}

const DEFAULT_DB = buildIndex(DATA);

// "Заводская, Ижевск" -> {name: "Заводская", qualifier: "Ижевск"}. Some
// titles contain commas themselves ("Кутузовская, МЦК"): a text that is a
// whole title stays a name.
function parse(query, db) {
  const text = String(query ?? "").trim();
  const comma = text.indexOf(",");
  if (comma < 0 || nameMatches(normalize(text), db)[0]?.level === 0) return { name: text, qualifier: "" };
  return { name: text.slice(0, comma).trim(), qualifier: text.slice(comma + 1).trim() };
}

// How well a station title matches a typed name: 0 exact, 1 prefix,
// 2 word-by-word abbreviation ("Екатеринбург-Пассажирский" ~ "Екатеринбург-Пасс."),
// 3 substring, -1 no match. The Moscow-only resolver had 0, 1 and 3.
function matchLevel(station, n, nWords) {
  const t = station.norm;
  if (t === n) return 0;
  if (t.startsWith(n)) return 1;
  if (nWords.length === station.words.length
      && nWords.every((w, i) => w.startsWith(station.words[i]) || station.words[i].startsWith(w))) return 2;
  if (t.includes(n)) return 3;
  return -1;
}

// Qualifier words must each match a word of the city, region, direction or
// title; a shared stem of 5+ letters counts ("Удмуртия" ~ "Удмуртская").
function matchesQualifier(station, qualifier) {
  station.placeWords ??= [station.settlement, station.region, station.direction, station.title]
    .flatMap((p) => normalize(p).split(" ")).filter(Boolean);
  const words = normalize(qualifier).split(" ").filter(Boolean)
    .flatMap((w) => (ALIASES.get(w) ?? w).split(" "));
  return words.every((w) => station.placeWords.some((p) => p.startsWith(w) || commonPrefix(p, w) >= 5));
}

function commonPrefix(a, b) {
  let i = 0;
  while (i < a.length && i < b.length && a[i] === b[i]) i++;
  return i;
}

// Candidate stations for one typed name, best matches first, Moscow first
// among equals (the old resolver only knew Moscow), then in table order.
function candidates(query, db) {
  const { name, qualifier } = parse(query, db);
  if (CODE_RE.test(name)) {
    const s = db.byCode.get(name);
    return [{ station: s ?? { code: name, title: name, direction: "", unknown: true }, level: 0 }];
  }
  const n = normalize(name);
  if (!n) return [];
  const found = qualifier ? nameMatches(n, db).filter((c) => matchesQualifier(c.station, qualifier)) : nameMatches(n, db);
  return found.slice(0, MAX_CANDIDATES);
}

// Every station matching a normalized name, sorted. One scan of the table per
// name and isolate: the same names come from every watch on a route.
function nameMatches(n, db) {
  let found = db.byName.get(n);
  if (found) return found;
  const nWords = n.split(" ");
  found = [];
  for (const station of db.stations) {
    const level = matchLevel(station, n, nWords);
    if (level >= 0) found.push({ station, level });
  }
  found.sort((x, y) => x.level - y.level || y.station.moscow - x.station.moscow || x.station.index - y.station.index);
  if (db.byName.size >= NAME_CACHE_MAX) db.byName.delete(db.byName.keys().next().value);
  db.byName.set(n, found);
  return found;
}

function distanceKm(a, b) {
  if (a.unknown || b.unknown) return 0; // a raw code: trust the user
  // Without coordinates a station in the same region is plausible but never
  // closer than one whose position is known.
  if (a.lat === null || b.lat === null) return a.region === b.region ? UNKNOWN_KM : Infinity;
  const rad = Math.PI / 180;
  const dLat = (b.lat - a.lat) * rad;
  const dLon = (b.lon - a.lon) * rad;
  const h = Math.sin(dLat / 2) ** 2 + Math.cos(a.lat * rad) * Math.cos(b.lat * rad) * Math.sin(dLon / 2) ** 2;
  return 12742 * Math.asin(Math.sqrt(h));
}

// Resolves Home and Work together.
// Returns {a, b} as {code, title, direction}, or
// {error: {reason: "notfound"|"ambiguous", which: "a"|"b", q, options?}}.
function resolvePair(queryA, queryB, db = DEFAULT_DB) {
  const ca = candidates(queryA, db);
  if (!ca.length) return { error: { reason: "notfound", which: "a", q: String(queryA ?? "") } };
  const cb = candidates(queryB, db);
  if (!cb.length) return { error: { reason: "notfound", which: "b", q: String(queryB ?? "") } };

  let pairs = [];
  for (const x of ca) {
    for (const y of cb) {
      if (x.station.code !== y.station.code) {
        pairs.push({ a: x.station, b: y.station, level: x.level + y.level, km: distanceKm(x.station, y.station) });
      }
    }
  }
  if (!pairs.length) return { a: toStation(ca[0].station), b: toStation(cb[0].station) };

  // Prefer pairs within a suburban trip, then the best name match, then the closest.
  const near = pairs.filter((p) => p.km <= MAX_ROUTE_KM);
  if (near.length) pairs = near;
  const level = Math.min(...pairs.map((p) => p.level));
  pairs = pairs.filter((p) => p.level === level).sort((x, y) => x.km - y.km);
  const best = pairs[0];

  // Pairs about as close as the best are real alternatives.
  const reach = Math.max(3 * best.km, best.km + 100);
  const contenders = pairs.filter((p) => p.km <= reach);
  const aCodes = new Set(contenders.map((p) => p.a.code));
  const bCodes = new Set(contenders.map((p) => p.b.code));
  const decided = aCodes.size === 1 && bCodes.size === 1;

  // Existing settings keep working: where the Moscow-only resolver found both
  // names, its answer stands unless the closest pair is also in Moscow (then
  // it is the better pick of two Moscow homonyms) or matches the names better.
  const legacy = legacyPair(queryA, queryB, db);
  if (legacy && legacy.level <= level && !(decided && best.a.moscow && best.b.moscow)) {
    return { a: toStation(legacy.a), b: toStation(legacy.b) };
  }
  if (decided) return { a: toStation(best.a), b: toStation(best.b) };

  const which = aCodes.size > 1 ? "a" : "b";
  const choices = [...new Map(contenders.map((p) => [p[which].code, p[which]])).values()]
    .sort((x, y) => x.index - y.index)
    .slice(0, MAX_OPTIONS);
  return {
    error: {
      reason: "ambiguous",
      which,
      q: String(which === "a" ? queryA : queryB),
      options: choices.map((s) => inputFor(s, db)),
    },
  };
}

// The pair the Moscow-only resolver (before all of Russia) gave for these
// names: the first Moscow station by exact name, else prefix, else substring.
// Null when a name has a qualifier or no Moscow match, or the pair is too far
// apart to be one trip.
function legacyPair(queryA, queryB, db) {
  const a = legacyStation(queryA, db);
  const b = a && legacyStation(queryB, db);
  if (!b || distanceKm(a.station, b.station) > MAX_ROUTE_KM) return null;
  return { a: a.station, b: b.station, level: a.level + b.level };
}

function legacyStation(query, db) {
  const { name, qualifier } = parse(query, db);
  if (qualifier || CODE_RE.test(name)) return null;
  const n = normalize(name);
  if (!n) return null;
  let best = null;
  for (const c of nameMatches(n, db)) {
    if (!c.station.moscow) continue;
    // The old resolver had no abbreviation level: such a title only matched as a substring.
    const level = c.level === 2 ? (c.station.norm.includes(n) ? 3 : -1) : c.level;
    if (level >= 0 && (!best || level < best.level)) best = { station: c.station, level };
  }
  return best;
}

// The shortest text that names exactly this station: its title, or the title
// with the city, region or direction after a comma, or the code.
function inputFor(station, db) {
  const hints = ["", station.settlement, station.region, station.direction];
  for (const [i, hint] of hints.entries()) {
    if (i > 0 && !hint) continue;
    const text = hint ? `${station.title}, ${hint}` : station.title;
    const found = candidates(text, db);
    const top = found.filter((c) => c.level === found[0].level);
    if (top.length === 1 && top[0].station.code === station.code) return text;
  }
  return station.code;
}

function searchStations(query, db = DEFAULT_DB, limit = 10) {
  if (!normalize(parse(query, db).name)) return [];
  return candidates(query, db)
    .filter((c) => !c.station.unknown)
    .slice(0, limit)
    .map(({ station: s }) => ({
      code: s.code,
      title: s.title,
      direction: s.direction,
      region: s.region,
      settlement: s.settlement,
      input: inputFor(s, db),
    }));
}

function toStation(s) {
  return { code: s.code, title: s.title, direction: s.direction };
}

module.exports = { normalize, buildIndex, upgrade, resolvePair, searchStations };
